# Extract primary CPC codes (first=true) for each citing patent
def get_primary_cpcs(cpc_json):
    try:
        data = json.loads(cpc_json)
    except Exception:
        return []
    return [c['code'] for c in data if c.get('first')]

# Subclass = first 4 chars of the code (e.g., 'G01V', 'H01M', 'C30B', 'H01L')
def get_subclass(code):
    # CPC subclass is first letter + 2 digits + 1 letter
    m = re.match(r'^([A-Z]\d{2}[A-Z])', code)
    if m:
        return m.group(1)
    return None

results = []
for cp in citing_patents:
    info = cp[0]
    primaries = get_primary_cpcs(cp[1])
    subclasses = set()
    for p in primaries:
        sc = get_subclass(p)
        if sc:
            subclasses.add(sc)
    # Extract assignee from Patents_info
    print("Info:", info)
    print("Primary CPCs:", primaries)
    print("Subclasses:", subclasses)
    print()
    results.append((info, list(subclasses)))

